import { IMPOSSIBLE, VersionInfo } from '@start9labs/start-sdk'

const notes = [
  'Updates Bitcoin Knots to 29.5 (bug fixes in networking and in how block and undo files are read and written). The coinbase maturity rules are unchanged from 29.4.3: bitcoins generated by block 979919 or later mature after 25920 blocks (about 180 days) until RDTS expires in September 2027, and those from blocks 973440 to 979918 after 6480.',
  "From 29.4.3:1: Fixes fetching older blocks on a pruned node. Peers running Knots 29.4.3 ignored the RPC proxy's requests for any block after the chain split, so Electrs Pruned stopped indexing at the first such block it needed that this node had already dropped, and Mempool and wallets could not look up those blocks either. The proxy now identifies itself to peers as following the BLAKE2b chain. An index that stopped resumes after this update, with no reindex.",
  'From 29.4.3:0: Updates Bitcoin Knots to 29.4.3. Bitcoins generated by block 979919 or later do not mature until 25920 blocks (about 180 days) later, until RDTS expires in September 2027; bitcoins generated by blocks 973440 to 979918 keep the 45-day maturity from 29.4.2.',
  'Block 979919 has passed, so a node updating from before 29.4.3 rechecks the blocks from 979919 at its first start, and a pruned node may need to re-sync.',
  'If you run Electrs Pruned, update it to 0.11.1:48 or later first: Knots 29.4.3 stops serving blocks past the chain split to Electrs before that version, and indexing stops.',
  'The node now also counts data hidden in unreachable script branches and in BPUB files against its data carrier limits, so it relays and mines fewer such transactions.',
  'The package version now starts with the Knots version it carries: 29.4.3:0 is Bitcoin Knots 29.4.3, revision 0 of this package. It replaces the 1.0.0 numbering, and updates from it work as before.',
  'From 1.0.0:41: Other Settings has a new Block Reserved Weight setting, Download UTXO Snapshot works with https links, and the package is built with start-sdk 3.1.0.',
].join(' ')

export const current = VersionInfo.of({
  version: '29.5.0:0',
  releaseNotes: {
    en_US: notes,
    es_ES: notes,
    de_DE: notes,
    pl_PL: notes,
    fr_FR: notes,
  },
  migrations: {
    // Nothing to migrate: 29.5 reads 29.4.3's data directory as it is.
    up: async ({ effects }) => {},
    down: IMPOSSIBLE,
  },
})
